]

def extract_region(grid, start_col):
    """Extract 4x4 region starting at start_col"""
    rows = []
    for r in range(4):
        row = [grid[r][c] for c in range(start_col, start_col + 4)]
        rows.append(row)
    return rows

regions = []
for start_col in [0, 5, 10, 15]:
    regions.append(extract_region(input_grid, start_col))

