# Extract patterns as binary (is there a non-zero at each position?)
def get_pattern(grid):
    pattern = []
    for r in range(4):
        row_pattern = []
        for c in range(4):
            # Check all 4 regions
            all_non_zero = True
            for reg in range(4):
                if reg == 0:
                    pos = reg * 4 + c  # region 0 starts at 0
                    val = grid[r][pos]
                else:
                    pos = reg * 5 + c + 1  # other regions with separator
                    val = grid[r][pos]
                if val == 0:
                    all_non_zero = False
                    break
            row_pattern.append(all_non_zero)
        pattern.append(row_pattern)
    return pattern

